            num += den
        else:
            den += num
        N //= 2
    return f"{num}/{den}"

def max_product(num_str: str, N: int, K: int) -> int:
    # Edge case: Invalid input
    if N < 1 or K < 1 or K > N - 1 or not num_str:
        raise ValueError("Invalid input")

    # Initialize the maximum product
    max_product = float('-inf')

    # Build all possible number combinations with K multiplications
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            number = float(num_str[:i]) * float(num_str[j:])
            if number > max_product:
                max_product = number

    return int(max_product)

