def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    # Fill dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            tail = beads[j]
            max_energy = 0
            for k in range(i, j):
                if beads[k] == tail:
                    energy = dp[i][k] * tail * beads[k + 1]
                    if energy > max_energy:
                        max_energy = energy
            dp[i][j] = max_energy

    return dp[0][n - 1]

