def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    decoded_message = ""

    for en, original in zip(encoded, original):
        if en not in mapping:
            mapping[en] = original[0]
        else:
            if original[0] != mapping[en]:
                return "Failed"

    for letter in message:
        if letter in mapping:
            decoded_message += mapping[letter]
        else:
            return "Failed"

    return decoded_message

