def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError('Input must be a positive integer greater than 1.')

    largest_prime = 1

    # Check for divisibility by 2
    while n % 2 == 0:
        largest_prime = 2
        n //= 2

    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            largest_prime = i
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        largest_prime = n

    return largest_prime

def count_partitions(n: int, k: int, x: int) -> int:
    if n < 0 or k < 0 or x < 0:
        raise ValueError("All input values must be non-negative.")
    if k == 0 and n > 0:
        return 0
    if k == 1 and n >= x:
        return 1
    if k == n:
        return 1
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(n + 1):
        dp[0][i] = 1  # One way to partition 0 into 0 parts (do nothing)
    for i in range(1, k + 1):
        for j in range(x, n + 1):
            for l in range(1, j + 1):
                dp[i][j] += dp[i - 1][j - l]
    return dp[k][n]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < n or last * 2 < n:
        return 0
    if n == 1:
        return 1
    if (n, last) in memo:
        return memo[(n, last)]
    result = 1
    while appendable(n, last):
        result += count_sequences(n + 1, n, memo)
    memo[(n, last)] = result
    return result

