def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if len(A) != len(B):
        return "NO ANSWER!"

    queue = [(A, 0)]
    visited = set()
    max_steps = 10

    while queue:
        current_string, steps = queue.pop(0)

        if current_string == B:
            return steps

        if steps >= max_steps:
            continue

        if current_string in visited:
            continue

        visited.add(current_string)

        for rule in rules:
            if current_string.startswith(rule[0]):
                new_string = current_string.replace(rule[0], rule[1])
                queue.append((new_string, steps + 1))

    return "NO ANSWER!"

