def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    def max_value(timeleft, i):
        if i == M:
            return 0
        # If time is too short to pick the current herb, skip it
        if timeleft - herbs[i][0] < 0:
            return max_value(timeleft, i + 1)
        # Take the current herb or skip it and choose the max of the two
        return max(herbs[i][1] + max_value(timeleft - herbs[i][0], i + 1), max_value(timeleft, i + 1))

    # Start the recursive function with full time left and the first herb
    return max_value(T, 0)

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(ch: str, shift: int) -> str:
        if not ch.isalpha():
            return ch
        ascii_offset = ord('A') if ch.isupper() else ord('a')
        shifted_val = (ord(ch) - ascii_offset + shift) % 26 + ascii_offset
        return chr(shifted_val)

    key_length = len(key)
    shifted_key = ''.join(shift_char(k, sum(ord(k) - ord('A') for k in key[:i])) for i in range(key_length))
    decrypted_text = ''.join(shift_char(c, -sum(shifted_key.count(k) - key.count(k)) for k in key) for c in ciphertext)

    return decrypted_text

