def hanoi_double_iterative(n: int) -> int:
    # Base cases for the recursion
    if n < 1:
        return 0

    # Recursive calculation
    return 8 * n * (n - 1) + 4 * (n - 2)

def total_smoked_cigarettes(n, k):
    if n <= 0 or k <= 0:
        raise ValueError("The number of cigarettes and butts must be positive.")
